import{_ as t,a as n}from"./chunks/inline-runtime-298.Fy-nlImh.js";import{_ as r,o as i,c as a,a3 as u}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Palette, zuletzt benutzt und Runtime","description":"Miniaturen, gespeicherte zuletzt benutzte Widgets und Runtime-Start/Stopp ab Studio 0.1.299.","frontmatter":{"title":"Palette, zuletzt benutzt und Runtime","description":"Miniaturen, gespeicherte zuletzt benutzte Widgets und Runtime-Start/Stopp ab Studio 0.1.299."},"headers":[],"relativePath":"projects/grafik-visual-studio/palette-runtime.md","filePath":"projects/grafik-visual-studio/palette-runtime.md","lastUpdated":1794565858000}'),s={name:"projects/grafik-visual-studio/palette-runtime.md"};function d(l,e,h,o,c,g){return i(),a("div",null,[...e[0]||(e[0]=[u('<h1 id="palette-zuletzt-benutzt-und-runtime" tabindex="-1">Palette, zuletzt benutzt und Runtime <a class="header-anchor" href="#palette-zuletzt-benutzt-und-runtime" aria-label="Permalink to &quot;Palette, zuletzt benutzt und Runtime&quot;">​</a></h1><p><strong>Studio 0.1.299</strong> enthält die neue Palette und die zuvor lokal als 0.1.298 geprüfte eingebettete Runtime. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/grafik-visual-studio-v0.1.299" target="_blank" rel="noreferrer">GitHub-Update</a>.</p><h2 id="miniaturen-und-beschreibungen" tabindex="-1">Miniaturen und Beschreibungen <a class="header-anchor" href="#miniaturen-und-beschreibungen" aria-label="Permalink to &quot;Miniaturen und Beschreibungen&quot;">​</a></h2><p>Die Palette zeigt drei gleichmäßige Kacheln pro Zeile: Miniatur oben, Name darunter. Messinstrumente verwenden ihren eigenen Renderer mit Vorschauwerten, Geräte und Uhr eigene statische Miniaturen. Vorhandene Paketbilder bleiben erhalten. Beim Darüberfahren oder Tastaturfokus erscheint eine größere Vorschau mit kurzer Beschreibung. UGSo-Sets und SVG-Line/LineBox/Math zeigen ausschließlich den Namen. Die Vorschau schaltet keine Geräte.</p><h2 id="zuletzt-benutzt" tabindex="-1">Zuletzt benutzt <a class="header-anchor" href="#zuletzt-benutzt" aria-label="Permalink to &quot;Zuletzt benutzt&quot;">​</a></h2><p>Direkt unter der Suche steht der unabhängig einklappbare Bereich <strong>Zuletzt benutzt</strong>. Er enthält bis zu <strong>zwölf unterschiedliche Widgettypen</strong>, den zuletzt eingefügten zuerst. Ein erneutes Einfügen verschiebt denselben Typ nach vorn; es entsteht kein zweiter Eintrag. Kacheln, Miniaturen und Beschreibungen entsprechen der normalen Palette.</p><p>Ein Klick fügt ein neues Widget mit den Standardwerten des Typs ein, <strong>keine Kopie des zuletzt bearbeiteten Widgets</strong>. Importieren, Einfügen aus der Zwischenablage und bloßes Auswählen ändern die Liste nicht. Die Palettensuche filtert auch die zuletzt benutzten Einträge. Nicht mehr installierte Pakettypen werden nicht angeboten; nach einer erneuten Installation können sie wieder erscheinen.</p><p>Liste und Klappzustand bleiben beim Neuladen und App-Update im <strong>gleichen Browserprofil und derselben Webadresse</strong> erhalten. Sie werden nicht zwischen Geräten synchronisiert und nicht in Projekte exportiert. Browserdaten löschen setzt sie zurück. Bei blockiertem Browserspeicher bleibt die Liste für die aktuelle Sitzung nutzbar. Andere Einstellungen und Projektdateien werden nicht verändert.</p><p><img src="'+t+'" alt="Zuletzt benutzte Widgets auf .177"></p><h2 id="runtime-direkt-uber-der-arbeitsflache" tabindex="-1">Runtime direkt über der Arbeitsfläche <a class="header-anchor" href="#runtime-direkt-uber-der-arbeitsflache" aria-label="Permalink to &quot;Runtime direkt über der Arbeitsfläche&quot;">​</a></h2><p><strong>▶</strong> neben den Seitenreitern speichert das aktuelle Projekt und startet eine isolierte Runtime über der Arbeitsfläche. <strong>■</strong> stoppt sie. Palette, Eigenschaften und Bearbeitungswerkzeuge sind währenddessen ausgegraut und gesperrt, einschließlich Tastenkürzeln. Seitenwechsel und das separate Runtime-Fenster bleiben bedienbar. Eine fehlgeschlagene Speicherung startet keine Runtime.</p><p>Stoppen stellt die bisherige Editorseite mit Auswahl, Verlauf und Scrollposition wieder bereit. Seitenwechsel der Vorschau ändern nicht die Editorseite. Eigene eingebettete Tabs behalten beim Start ihren Kontext. Die bisherigen Editor/Runtime-Moduslinks oben entfallen; <strong>Neuer Tab</strong> öffnet weiterhin die eigenständige Runtime. In der Runtime können vorhandene Widgets wie bisher echte HA-Geräte steuern.</p><p><img src="'+n+'" alt="Inline-Runtime mit ausgegrauten Editorwerkzeugen"></p><h2 id="erhalt-und-prufung" tabindex="-1">Erhalt und Prüfung <a class="header-anchor" href="#erhalt-und-prufung" aria-label="Permalink to &quot;Erhalt und Prüfung&quot;">​</a></h2><p>Bestehende Projekte, Widgettypen, CSS- und Farbeinstellungen bleiben erhalten. Neue Browserpräferenzen erhalten einen eigenen Speicherschlüssel. Kein VIS-2-Code oder -Bild wurde für diese Funktionen kopiert.</p><p>Am 8. November 2026 wurde 0.1.299 auf .177 (HA 2026.11.0/ARM64) und .193 (HA 2026.10.4/amd64) geprüft: zuletzt verwendete Miniaturen, Reihenfolge ohne Duplikate, Einfügen, Einklappen und Erhalt nach Neuladen sowie die Sperre während der Inline-Runtime. Testeinfügungen wurden rückgängig gemacht; die bestehenden 13 beziehungsweise 11 Widgets blieben erhalten. Palette und Start/Stopp waren zusätzlich mit Speichern, Seitenwechsel und Rückkehr zum Editor geprüft. 23 JavaScript- und 17 Python-Tests bestanden. Details: <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/docs" target="_blank" rel="noreferrer">Quellcode und Prüfberichte</a>.</p>',16)])])}const z=r(s,[["render",d]]);export{m as __pageData,z as default};
